import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
import { RestoreRefusedError } from "@/lib/soft-delete";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as issueService from "@/server/services/issue-service";
import * as attachmentService from "@/server/services/attachment-service";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import { NotFoundError } from "@/server/services/_support";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { toAppError } from "@/lib/errors";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());

it("restores and purges", async () => {
  const t = await createTenant("smoke");
  await usageRepo.recomputeUsage(t.org.id);
  const a = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "A" }));
  const b = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "B" }));
  await attachmentService.addAttachment(t.actors.member, { orgId: t.org.id, issueId: b.id, filename: "x", contentType: "text/plain", sizeBytes: 1500000 } as never);
  const before = await usageRepo.getUsage(t.org.id);
  await expect(issueService.restoreIssue(t.actors.member, t.org.id, a.id)).rejects.toBeInstanceOf(RestoreRefusedError);
  await issueService.archiveIssue(t.actors.member, t.org.id, a.id);
  const r = await issueService.restoreIssue(t.actors.member, t.org.id, a.id);
  expect(r.archivedAt).toBeNull();
  expect(r.number).toBe(a.number);
  expect((await usageRepo.getUsage(t.org.id)).issuesUsed).toBe(before.issuesUsed);
  const acts = await activityRepo.listActivity({ orgId: t.org.id, limit: 100, cursor: null } as never);
  expect(acts.items.some((x) => x.action === "issue.restored")).toBe(true);

  await issueService.archiveIssue(t.actors.member, t.org.id, b.id);
  const later = new Date(Date.now() + 400 * 24 * 3600 * 1000);
  const res = await runCleanupArchivedJob(later);
  expect(res.failed).toBe(0);
  expect(await issueRepo.findIssueById(t.org.id, b.id)).toBeNull();
  const after = await usageRepo.getUsage(t.org.id);
  expect(after.storageMbUsed).toBe(before.storageMbUsed - 2);
  await expect(issueService.restoreIssue(t.actors.member, t.org.id, b.id)).rejects.toBeInstanceOf(NotFoundError);
  expect(await issueRepo.nextIssueNumber(t.org.id, t.project.id)).toBe(b.number + 1);
  const err = toAppError(new RestoreRefusedError("Issue", "x", "quota"));
  expect(err.code).toBe("conflict");
});
